async function submitDisposition(e){e.preventDefault();const f=new FormData(e.currentTarget),reason=String(f.get("reason")||"").trim(),action=String(f.get("action")||"accept"),meta=qualityActionMeta[action];if(!reason)throw new Error("必须填写判断依据，说明核查来源和原因");if(!window.confirm(`${meta.label}\n\n本次会做：${meta.impact}\n\n下一步：${meta.next}\n\n确认提交？`))return;const body={action,reason,operator:"local-user"};if(body.action==="correct"){body.before=JSON.parse(String(f.get("before")||"{}"));body.after=JSON.parse(String(f.get("after")||"{}"))}await api(`/api/data-center/quality/issues/${encodeURIComponent(state.issue)}/disposition`,{method:"POST",body});await Promise.all([loadQuality(),qualityDetail(state.issue)]);feedback(`已完成“${meta.label}”。${meta.next}`,"success")}
